const sendingClaim = `-- name: SendingClaim :many

WITH picked AS (
    SELECT m.id FROM messages m
    WHERE m.campaign_id = $1 AND m.provider_id = $2 AND m.mailbox_provider = $3
      AND m.status = 'queued'
      AND (m.claimed_at IS NULL OR m.claimed_at < $4::timestamptz)
      AND (m.next_attempt_at IS NULL OR m.next_attempt_at <= $5::timestamptz)
    ORDER BY m.id
    LIMIT $6
    FOR UPDATE SKIP LOCKED
), upd AS (
    UPDATE messages m SET claimed_at = $5::timestamptz, attempts = m.attempts + 1
    FROM picked WHERE m.id = picked.id
    RETURNING m.id, m.workspace_id, m.contact_id, m.email, m.variant, m.mailbox_provider, m.attempts
)
SELECT upd.id, upd.contact_id, upd.email, upd.variant, upd.mailbox_provider, upd.attempts,
       coalesce(c.first_name, '')::text AS first_name, coalesce(c.last_name, '')::text AS last_name,
       coalesce(c.attributes, '{}'::jsonb)::jsonb AS attributes, coalesce(c.tier, '')::text AS tier,
       coalesce(c.source, '')::text AS source, (c.last_human_open_at IS NOT NULL)::boolean AS engaged,
       (c.id IS NULL OR c.erased_at IS NOT NULL OR c.status <> 'active')::boolean AS gone,
       EXISTS (SELECT 1 FROM suppressions s WHERE s.workspace_id = upd.workspace_id AND s.email = upd.email)::boolean AS suppressed
FROM upd
LEFT JOIN contacts c ON c.id = upd.contact_id
ORDER BY upd.id
`

type SendingClaimParams struct {
	CampaignID      *uuid.UUID `json:"campaignId"`
	ProviderID      *uuid.UUID `json:"providerId"`
	MailboxProvider string     `json:"mailboxProvider"`
	Stale           time.Time  `json:"stale"`
	Now             time.Time  `json:"now"`
	Lim             int32      `json:"lim"`
}

type SendingClaimRow struct {
	ID              uuid.UUID       `json:"id"`
	ContactID       *uuid.UUID      `json:"contactId"`
	Email           string          `json:"email"`
	Variant         string          `json:"variant"`
	MailboxProvider string          `json:"mailboxProvider"`
	Attempts        int16           `json:"attempts"`
	FirstName       string          `json:"firstName"`
	LastName        string          `json:"lastName"`
	Attributes      json.RawMessage `json:"attributes"`
	Tier            string          `json:"tier"`
	Source          string          `json:"source"`
	Engaged         bool            `json:"engaged"`
	Gone            bool            `json:"gone"`
	Suppressed      bool            `json:"suppressed"`
}

// Send loop -------------------------------------------------------------
// Claims up to lim queued messages of one sending provider and mailbox
// provider, oldest first, skipping rows another worker holds. A claim older
// than the stale time belonged to a worker that died.
func (q *Queries) SendingClaim(ctx context.Context, arg SendingClaimParams) ([]SendingClaimRow, error) {
	rows, err := q.db.Query(ctx, sendingClaim,
		arg.CampaignID,
		arg.ProviderID,
		arg.MailboxProvider,
		arg.Stale,
		arg.Now,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SendingClaimRow{}
	for rows.Next() {
		var i SendingClaimRow
		if err := rows.Scan(
			&i.ID,
			&i.ContactID,
			&i.Email,
			&i.Variant,
			&i.MailboxProvider,
			&i.Attempts,
			&i.FirstName,
			&i.LastName,
			&i.Attributes,
			&i.Tier,
			&i.Source,
			&i.Engaged,
			&i.Gone,
			&i.Suppressed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

