const sendingReserve = `-- name: SendingReserve :one
UPDATE sending_rate_windows
SET last_grant = least($1::int, $2::int - used),
    used = used + least($1::int, $2::int - used)
WHERE provider_id = $3 AND sec = $4 AND used < $2::int
RETURNING last_grant
`

type SendingReserveParams struct {
	Want       int32     `json:"want"`
	Cap        int32     `json:"cap"`
	ProviderID uuid.UUID `json:"providerId"`
	Sec        int64     `json:"sec"`
}

// Reserves up to want sends in a provider's one-second window of cap (open
// it first). No row comes back when the window is full.
func (q *Queries) SendingReserve(ctx context.Context, arg SendingReserveParams) (int32, error) {
	row := q.db.QueryRow(ctx, sendingReserve,
		arg.Want,
		arg.Cap,
		arg.ProviderID,
		arg.Sec,
	)
	var last_grant int32
	err := row.Scan(&last_grant)
	return last_grant, err
}

